import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> dict with side, price, qty, active
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                top_price, top_seq, top_oid = sell_heap[0]
                if typ != 'market' and top_price > price:
                    break
                top_info = book[top_oid]
                trade_qty = min(remaining, top_info['qty'])
                trades.append([oid, top_oid, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] <= 0:
                    top_info['active'] = False
                    heapq.heappop(sell_heap)
                # if trade_qty consumed all remaining or top qty, loop continues

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                seq_counter += 1
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                # for market/ioc, discard remainder, but still record if fully processed order id (not needed)
                if typ == 'limit':
                    # remaining == 0, order fully filled, no need to add to book but can add entry
                    book[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'active': False}
                else:
                    book[oid] = {'side': 'buy', 'price': price if price is not None else None, 'qty': 0, 'active': False}

        else:  # side == 'sell'
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, top_seq, top_oid = buy_heap[0]
                top_price = -negprice
                if typ != 'market' and top_price < price:
                    break
                top_info = book[top_oid]
                trade_qty = min(remaining, top_info['qty'])
                trades.append([top_oid, oid, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] <= 0:
                    top_info['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                seq_counter += 1
                heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                if typ == 'limit':
                    book[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'active': False}
                else:
                    book[oid] = {'side': 'sell', 'price': price if price is not None else None, 'qty': 0, 'active': False}

    return trades

